import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 7 Homework — Debug your own app","description":"","frontmatter":{"source":"weeks/07-read-and-debug/homework.md"},"headers":[],"relativePath":"weeks/07-read-and-debug/homework.md","filePath":"weeks/07-read-and-debug/homework.md"}'),n={name:"weeks/07-read-and-debug/homework.md"};function i(s,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-7-homework--debug-your-own-app" tabindex="-1">Week 7 Homework — Debug your own app <a class="header-anchor" href="#week-7-homework--debug-your-own-app" aria-label="Permalink to &quot;Week 7 Homework — Debug your own app&quot;">​</a></h1><p><strong>Due before next week&#39;s Studio A</strong> (week 8; default 11:59 pm the night before) · <strong>Core:</strong> about 5¼ hours, including project time, required · <strong>Stretch:</strong> optional</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>In your <strong>public Project 1 repository</strong>:</p><ul><li>☐ Your app checked for the clinic&#39;s five bugs (🔴 AI off), and what you found fixed (<a href="#1-the-five-bugs-in-your-own-code-45-min">task 1</a>)</li><li>☐ <code>TESTS.md</code> extended: a manual test for every criterion and <strong>at least 3 edge-case tests</strong>, run on your live site and dated (<a href="#2-hunt-for-edge-cases-1-h-15-min">task 2</a>)</li><li>☐ A first draft of &quot;How it works&quot; in your README, written by you (<a href="#3-trace-one-action-through-your-code-45-min">task 3</a>)</li><li>☐ Failing MUST criteria fixed, or listed in &quot;Known issues&quot; (<a href="#4-fix-what-still-fails-about-2-h">task 4</a>)</li><li>☐ <code>PROMPTS.md</code>: a check written first and a teach-back for every AI-written fix</li></ul><p>Also: your week 7 reflection on <strong>Canvas</strong>, written without AI (<a href="#5-reflection-on-canvas-30-min">task 5</a>); codespaces stopped.</p><h2 id="time-plan" tabindex="-1">Time plan <a class="header-anchor" href="#time-plan" aria-label="Permalink to &quot;Time plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Kind</th><th>Time</th></tr></thead><tbody><tr><td>1. The five bugs in your own code</td><td>Homework</td><td>45 min</td></tr><tr><td>2. Hunt for edge cases</td><td>Homework</td><td>1 h 15 min</td></tr><tr><td>3. Trace one action through your code</td><td>Homework</td><td>45 min</td></tr><tr><td>4. Fix what still fails</td><td>Project time</td><td>about 2 h</td></tr><tr><td>5. <code>PROMPTS.md</code> and reflection on Canvas</td><td>Journal</td><td>30 min</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>about 5¼ h</strong></td></tr></tbody></table><p>Work in your Project 1 Codespace. 🟢 AI on for fixing: Copilot&#39;s <strong>Ask</strong> mode or your chat assistant, no agent mode yet (week 11). Use <a href="./../../resources/safe-loop.html">the Safe Loop</a> for every change: <strong>check first</strong>, one step, test, read the diff, <strong>teach back</strong>, commit.</p><hr><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><h3 id="1-the-five-bugs-in-your-own-code-45-min" tabindex="-1">1. The five bugs in your own code (45 min) <a class="header-anchor" href="#1-the-five-bugs-in-your-own-code-45-min" aria-label="Permalink to &quot;1. The five bugs in your own code (45 min)&quot;">​</a></h3><p>🔴 <strong>AI off for the checking.</strong> Fixing what you find can use AI.</p><p>The clinic&#39;s bugs are the most common bugs in beginner apps, AI-written or not. Look for each one in your Project 1:</p><table tabindex="0"><thead><tr><th>Clinic bug</th><th>Check your Project 1</th></tr></thead><tbody><tr><td>1. A missing comma stopped the whole script</td><td>Reload with the Console open. Is it free of red errors?</td></tr><tr><td>2. An id that didn&#39;t match the HTML</td><td>For every <code>getElementById(&quot;…&quot;)</code> in <code>app.js</code>, search <code>index.html</code> for that exact id</td></tr><tr><td>3. Text added to a number (<code>40 + &quot;5&quot;</code>)</td><td>Does your app read a number from an input box? Is it converted with <code>Number(...)</code> before any arithmetic?</td></tr><tr><td>4. A position on screen used as a position in the data</td><td>If your list is ever filtered or sorted, delete the top item in that view. Did the right one go?</td></tr><tr><td>5. Saving without <code>JSON.stringify</code></td><td>Does every <code>setItem</code> save <code>JSON.stringify(...)</code>, and every <code>getItem</code> go through <code>JSON.parse(...)</code>?</td></tr></tbody></table><p>Write down what you find, with the steps to reproduce it, under &quot;Bugs found by testing&quot; in <code>TESTS.md</code>. &quot;Nothing found, here&#39;s how I checked&quot; is a good result. Then fix each bug, one commit each.</p><h3 id="2-hunt-for-edge-cases-1-h-15-min" tabindex="-1">2. Hunt for edge cases (1 h 15 min) <a class="header-anchor" href="#2-hunt-for-edge-cases-1-h-15-min" aria-label="Permalink to &quot;2. Hunt for edge cases (1 h 15 min)&quot;">​</a></h3><p>Extend the <code>TESTS.md</code> you started in week 6 (the <a href="./../../templates/TESTS.html">TESTS template</a> has the layout):</p><ul><li>At least <strong>one manual test for every acceptance criterion</strong>: numbered steps and the expected result.</li><li>At least <strong>three edge-case tests</strong>, marked &quot;(edge case)&quot;. Pick from: empty input, very long input (paste 500 characters), duplicates, special characters such as <code>&lt;b&gt;hi&lt;/b&gt;</code> and emoji, reloading, a first visit with nothing saved (clear Local Storage in DevTools), a small phone screen (DevTools device mode: the phone-and-tablet icon).</li><li>Run every test <strong>on your live site</strong> and record the result with the date.</li><li>Log every failure under <strong>Bugs found by testing</strong>. A test that failed and then passed after a fix is the best evidence you can show.</li></ul><p>If <code>&lt;b&gt;hi&lt;/b&gt;</code> shows up <strong>bold</strong>, your app is treating typed text as code. Ask the AI why, and fix it (the usual fix is <code>textContent</code> instead of <code>innerHTML</code>; see <a href="./../../resources/glossary.html#innerhtml-and-textcontent">innerHTML and textContent</a>).</p><p>Next week, edge cases in pure logic become automated tests: note which ones are about a calculation or a check rather than the page.</p><h3 id="3-trace-one-action-through-your-code-45-min" tabindex="-1">3. Trace one action through your code (45 min) <a class="header-anchor" href="#3-trace-one-action-through-your-code-45-min" aria-label="Permalink to &quot;3. Trace one action through your code (45 min)&quot;">​</a></h3><p>🔴 <strong>AI off for the tracing.</strong> &quot;What happens when I click [your main button]?&quot; is the first question to be able to answer about any app you build.</p><p>Follow your app&#39;s main action through the code and write the path down as a numbered list: the event listener, the function it calls, where it reads the input, how it changes the list in memory, where it saves, and where it redraws the page. Turn that into 3–6 sentences under <strong>How it works</strong> in your README (from the <a href="./../../templates/PROJECT_README.html">Project README template</a>). Anything you can&#39;t explain goes on your list for task 4: ask the AI (Ask mode) to explain it, then rewrite the sentence yourself.</p><h3 id="4-fix-what-still-fails-about-2-h" tabindex="-1">4. Fix what still fails (about 2 h) <a class="header-anchor" href="#4-fix-what-still-fails-about-2-h" aria-label="Permalink to &quot;4. Fix what still fails (about 2 h)&quot;">​</a></h3><ol><li>Open your README&#39;s acceptance table and <code>SPEC.md</code>. List the MUST criteria that don&#39;t pass yet, plus anything tasks 1–3 found.</li><li>Fix them one at a time. For each: write the check first (an automated test if the fix is in a pure function, as in week 6; otherwise a manual test in <code>TESTS.md</code>); reproduce the failure and read the Console; fix it yourself or with AI help; test in the preview; read the diff; teach back any AI-written change; commit (<code>Fix AC4: stop button saves session</code>).</li><li>If the spec was wrong or too big, change <code>SPEC.md</code> instead and say why in the commit message. Moving a MUST to SHOULD is allowed if you explain it in your README&#39;s &quot;Known issues&quot;.</li></ol><p>✅ <strong>Checkpoint:</strong> every fix is its own commit, and the acceptance table in your README says honestly what passes.</p><h3 id="5-reflection-on-canvas-30-min" tabindex="-1">5. Reflection on Canvas (30 min) <a class="header-anchor" href="#5-reflection-on-canvas-30-min" aria-label="Permalink to &quot;5. Reflection on Canvas (30 min)&quot;">​</a></h3><p>Use the four headings of the <a href="./../../templates/REFLECTION.html">reflection template</a>, on Canvas. Anchor it in a concrete moment from the Debug Clinic: an error message you read, a hypothesis that turned out wrong, the moment you found the line. Then answer in two or three sentences: which of the five clinic bugs would you have been least likely to spot in your own code, and why?</p><blockquote><p>🔴 <strong>AI off.</strong> 150–300 words, graded on specifics, not polish (<a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">reflection rubric</a>). It goes on Canvas, not in your repository.</p></blockquote><p>Also add this week&#39;s prompts, checks and teach-backs to <code>PROMPTS.md</code>.</p><hr><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> your Project 1 runs in its Codespace preview, and you&#39;ve checked it for the five clinic bugs. Week 8 finishes Project 1, and its automated tests build on <code>TESTS.md</code>.</p><p><strong>Fallen behind?</strong> Tell your instructor early. A <a href="./../../assessment/#late-work-and-grace-tokens">grace token</a> can buy you time on Project 1, and the <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">rescue starter</a> is a working tool you can continue from.</p></div><hr><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><h3 id="a-breakpoints" tabindex="-1">A. Breakpoints <a class="header-anchor" href="#a-breakpoints" aria-label="Permalink to &quot;A. Breakpoints&quot;">​</a></h3><p>In DevTools → <strong>Sources</strong>, set a breakpoint in your draw function and step through it once with a real list. Write down one thing you learned about your own code.</p><h3 id="b-the-clinic-harder" tabindex="-1">B. The clinic, harder <a class="header-anchor" href="#b-the-clinic-harder" aria-label="Permalink to &quot;B. The clinic, harder&quot;">​</a></h3><p>Ask your instructor for a harder bonus bug and fix it in your <code>debug-clinic</code> repository, with a claim in <code>BUGS.md</code>. Or explain why <code>&quot;40&quot; &lt;= 0</code> gives a sensible answer in JavaScript but <code>40 + &quot;5&quot;</code> doesn&#39;t (Python raises a <code>TypeError</code> for both).</p>',39)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
